// Build the ticket record. This is the only place a ticket is created.
const inp = $input.first().json;

const pad = (n) => String(n).padStart(4, '0');
const rand = Math.floor(Math.random() * 10000);
const d = new Date();
const stamp = `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;
const reference = `RSA-${stamp}-${pad(rand)}`;

const CATEGORIES = ['plumbing','electrical','appliance','structural','damp_mould',
                    'pest','cleaning','security','internet','other'];
const URGENCIES  = ['emergency','high','normal','low'];
const PHOTO      = ['provided','refused','none'];

// The agent fills these through $fromAI, so they arrive as strings and can be
// '', 'null' or 'undefined'. Postgres rejects those for a uuid column with a
// 400, which is opaque by the time n8n reports it. Normalise here.
const uuid = (v) => {
  const s = (v ?? '').toString().trim();
  if (!s || s === 'null' || s === 'undefined') return null;
  return /^[0-9a-f-]{36}$/i.test(s) ? s : null;
};
const str = (v) => {
  const s = (v ?? '').toString().trim();
  return s && s !== 'null' && s !== 'undefined' ? s : null;
};
const num = (v) => {
  const f = parseFloat(v);
  return Number.isFinite(f) ? f : null;
};

const estate_id   = uuid(inp.estate_id);
const unit_id     = uuid(inp.unit_id);
const resident_id = uuid(inp.resident_id);

// unit_id and estate_id are NOT NULL in the schema. Failing here with a clear
// message beats a 400 from PostgREST that says nothing useful.
if (!estate_id || !unit_id) {
  throw new Error(
    `Cannot create ticket: estate_id or unit_id missing. ` +
    `Got estate_id="${inp.estate_id}", unit_id="${inp.unit_id}". ` +
    `If the resident is unregistered, register_resident must be called first ` +
    `and its unit_id passed through.`
  );
}

const category = CATEGORIES.includes(inp.category) ? inp.category : 'other';
const urgency  = URGENCIES.includes(inp.urgency)   ? inp.urgency  : 'normal';
const photo_status = PHOTO.includes(inp.photo_status) ? inp.photo_status : 'none';

const required = ['category','location_in_unit','description','onset','access_window'];
const missing = required.filter(k => !str(inp[k]));
const isEmergency = urgency === 'emergency' || inp.safety_flag === true
                    || inp.safety_flag === 'true';

const confidence = num(inp.confidence);

// A ticket whose photo was never accepted or explicitly refused goes to
// review, not the main queue. This is the database-side half of the photo
// rule: the prompt can drift, this cannot.
const photoUnresolved = !['provided','refused'].includes(photo_status);

const needsReview =
  (missing.length > 0 && !isEmergency) ||
  (photoUnresolved && !isEmergency) ||
  (confidence !== null && confidence < 0.7) ||
  (!CATEGORIES.includes(inp.category));

return [{
  json: {
    reference,
    estate_id,
    unit_id,
    resident_id,
    channel: str(inp.channel) ?? 'whatsapp',
    category,
    urgency,
    location_in_unit: str(inp.location_in_unit),
    description: str(inp.description),
    onset: str(inp.onset),
    access_window: str(inp.access_window),
    safety_flag: inp.safety_flag === true || inp.safety_flag === 'true',
    photo_status,
    photo_url: str(inp.photo_url),
    confidence,
    status: needsReview ? 'needs_review' : 'open',
    review_reason: needsReview
      ? (missing.length ? `missing_fields:${missing.join(',')}`
         : photoUnresolved ? 'photo_mismatch'
         : 'low_confidence')
      : null,
    missing_fields: missing,
    created_by: 'agent',
  }
}];

// Surface the real PostgREST error instead of n8n's generic "Bad request".
const r = $input.first().json;
if (r.statusCode >= 400) {
  const b = r.body;
  throw new Error(`Supabase rejected the ticket (${r.statusCode}): ` +
    (typeof b === 'string' ? b : JSON.stringify(b)));
}
return [{ json: Array.isArray(r.body) ? r.body[0] : r.body }];
